import numpy as np
for i in range(len(x)):
    x_i = x[i]
    y_i = y1[i]
    mask = (x_i >= 1550) & (x_i <= 1620)
    if np.any(mask):
        max_val = np.max(y_i[mask])
        if max_val != 0:
            y1[i] = y_i / max_val
    else:
        # Fallback to global max if G band is not present or zero
        max_val = np.max(y_i)
        if max_val != 0:
            y1[i] = y_i / max_val
